-- Supabase-Grundschema für Mission Control.
-- Öffentliche Nutzer sollen nur lesen; authentifizierte Admins dürfen schreiben.
create table if not exists public.app_settings(id bigint generated by default as identity primary key,event_title text,event_subtitle text,intro text,heading_morning text,heading_midday text,heading_evening text,instagram_url text,tiktok_url text);
create table if not exists public.team_members(id uuid primary key default gen_random_uuid(),name text not null,email text unique,roles text[] default '{}');
create table if not exists public.program_items(id uuid primary key default gen_random_uuid(),event_date date not null,start_time time not null,daypart text not null,title text not null,speaker text,description text,photographer text,story_coordinator text,story_maker text,reel_maker text,published boolean default true);
create table if not exists public.tasks(id uuid primary key default gen_random_uuid(),program_id uuid references public.program_items(id) on delete cascade,event_date date,start_time time,title text,owner text,role text,description text);
create table if not exists public.content_items(id uuid primary key default gen_random_uuid(),program_id uuid references public.program_items(id) on delete set null,event_date date,kind text,title text,description text,owner text,shoot_time time,publish_time time,social_url text,status text,published boolean default true);
create table if not exists public.content_images(id uuid primary key default gen_random_uuid(),content_id uuid references public.content_items(id) on delete cascade,image_url text,caption text);
alter table public.app_settings enable row level security;alter table public.team_members enable row level security;alter table public.program_items enable row level security;alter table public.tasks enable row level security;alter table public.content_items enable row level security;alter table public.content_images enable row level security;
create policy "public read settings" on public.app_settings for select using (true);create policy "public read team" on public.team_members for select using (true);create policy "public read program" on public.program_items for select using (published=true);create policy "public read tasks" on public.tasks for select using (true);create policy "public read content" on public.content_items for select using (published=true);create policy "public read images" on public.content_images for select using (true);
create policy "auth manage settings" on public.app_settings for all to authenticated using (true) with check (true);create policy "auth manage team" on public.team_members for all to authenticated using (true) with check (true);create policy "auth manage program" on public.program_items for all to authenticated using (true) with check (true);create policy "auth manage tasks" on public.tasks for all to authenticated using (true) with check (true);create policy "auth manage content" on public.content_items for all to authenticated using (true) with check (true);create policy "auth manage images" on public.content_images for all to authenticated using (true) with check (true);
